export type getPatientAppointmentsResponse =
	getPatientAppointmentsResponseSuccess;

export const getGetPatientAppointmentsUrl = (
	userId: string,
	params: GetPatientAppointmentsParams,
) => {
	const normalizedParams = new URLSearchParams();
	const formObjectParameters = new Map<string, string>([
		["pageable", "flatten"],
	]);

	Object.entries(params || {}).forEach(([key, value]) => {
		if (
			typeof value === "object" &&
			value !== null &&
			!Array.isArray(value) &&
			!(value instanceof Date) &&
			formObjectParameters.has(key)
		) {
			const commaParts: string[] = [];
			Object.entries(value).forEach(([subKey, subValue]) => {
				const items = (Array.isArray(subValue) ? subValue : [subValue])
					.filter((v) => v !== undefined)
					.map((v) =>
						v === null
							? "null"
							: v instanceof Date
								? v.toISOString()
								: typeof v === "object"
									? JSON.stringify(v)
									: String(v),
					);
				if (formObjectParameters.get(key) === "flatten") {
					items.forEach((item) => normalizedParams.append(subKey, item));
				} else if (items.length > 0) {
					commaParts.push(subKey, ...items);
				}
			});
			if (commaParts.length > 0) {
				normalizedParams.append(key, commaParts.join(","));
			}
			return;
		}

		if (value !== undefined) {
			normalizedParams.append(key, value === null ? "null" : String(value));
		}
	});

	const stringifiedParams = normalizedParams.toString();

	return stringifiedParams.length > 0
		? `/appointments/patient/${userId}?${stringifiedParams}`
		: `/appointments/patient/${userId}`;
};

